head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil05107";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — isOk

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_sessionFill();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil05107.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {

        //             alert(1);
        //
        //             alert(2);
        //                    checkSave();
        //                    alert(3);
        //

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05107.onpageload' }); }
};

// 세션 사용자 결선 (어휘 session_attribute 1건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["usrId"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil05107' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_saveAdjReq_onclick
 * @description 「저장」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_saveAdjReq_onclick = async function(e){
    try {
        await scwin.saveAdjReq()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05107.btn_saveAdjReq_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_saveAdjReq
 * @description save Adj Req 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_saveAdjReq = async function () {
    const sbmOptions = {
        id: "tx_fn_saveAdjReq",
        method: "post",
        action: "/list/listAdjReq.do",
        ref: "dma_saveAdjReqReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name saveAdjReq
 * @description save Adj Req 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveAdjReq = async function () {
    const opener = ((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {});
    const msg = "수정 승인 후 다시 접수 될때까지 같은 업무에 대해서 수정요청 할 수 없습니다. \r\n수정요청 하시겠습니까?";
    if (await scwin.checkValue()) {
        if (await $c.win.confirm(msg)) {
            const frm = (document.ListAdjReqForm || { elements: [] });
            frm.action = "listAdjReq.do";
            $c.util.getComponent('dma_saveAdjReqReq').set('method', "insertListAdjReq");
            frm.target = "adjReqWin";
            await scwin.tx_fn_saveAdjReq();
        }
    }
};

/**
 * @method
 * @name checkSave
 * @description check Save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkSave = async function () {
    const isOk = (String(((dma_pageContext.get("isOk") ?? "")) == null ? '' : ((dma_pageContext.get("isOk") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("isOk") ?? "")) == null ? '' : ((dma_pageContext.get("isOk") ?? ""))));
    if (isOk !== '') {
        if (isOk === 'true') {
            await $c.win.alert('수정요청 되었습니다.');
            let opener = ((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {});
            opener.calcelYn = 'N';
            $c.win.closePopup();
        } else {
            await $c.win.alert('수정요청 중 오류가 발생 되었습니다.');
            opener = ((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {});
            opener.calcelYn = 'N';
            $c.win.closePopup();
        }
    }
};

/**
 * @method
 * @name checkValue
 * @description check Value 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkValue = async function () {
    if ($c.util.getComponent('txa_chgRsn').getValue().length === 0) {
        await $c.win.alert('수정 사유를 입력 하세요.');
        return false;
    }
    return true;
};
